public bool AddToBalanceAndCreateIfNotExists(Address address, in UInt256 balance, IReleaseSpec spec)
{
    if (AccountExists(address))
    {
        AddToBalance(address, balance, spec);
        return false;
    }
    else
    {
        CreateAccount(address, balance);
        return true;
    }
}

