{
    Task codeFlushTask = !commitRoots || _codeBatch is null || _codeBatch.Count == 0
        ? Task.CompletedTask
        : CommitCodeAsync();

    bool isTracing = _logger.IsTrace;
    int stepsBack = _changes.Count - 1;

